import{_ as p,a0 as o,w as u,s as a,ao as d,I as s,x as n,a1 as r,A as e}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const x=JSON.parse('{"title":"每日Ubuntu小技巧-使用Windows共享打印機進行打印 | LCTT x X-CMD","titleTemplate":false,"description":"每日Ubuntu小技巧-使用Windows共享打印機進行打印 | LCTT (201312) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"每日Ubuntu小技巧-使用Windows共享打印機進行打印 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"每日Ubuntu小技巧-使用Windows共享打印機進行打印 | LCTT (201312) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201312/Daily Ubuntu Tips – Print From Shared Windows Printers","title":"每日Ubuntu小技巧-使用Windows共享打印機進行打印","tag":"201312","desc":""},"relativePath":"201312/Daily Ubuntu Tips – Print From Shared Windows Printers.md","filePath":"[post].md"}'),w={name:"201312/Daily Ubuntu Tips – Print From Shared Windows Printers.md"};function l(g,t,b,m,T,W){const i=o("Link");return u(),a("div",null,[t[11]||(t[11]=d(`<h1 id="每日ubuntu小技巧-使用windows共享打印機進行打印" tabindex="-1">每日Ubuntu小技巧-使用Windows共享打印機進行打印 <a class="header-anchor" href="#每日ubuntu小技巧-使用windows共享打印機進行打印" aria-label="Permalink to “每日Ubuntu小技巧-使用Windows共享打印機進行打印”">​</a></h1><p>對於那些既有Windows電腦又有Ubuntu電腦但卻只有一台打印機的用户，這篇博文向你展示如何在Windows中共享一個打印機，並允許Ubuntu使用它來打印。</p><p>幾乎所有的打印機都默認支持Windows系統。許多打印機生產商都為Windows生產打印機，但為包括Ubuntu在內的Linux系統生產的並不多。所以，假如你有一台支持Windows的打印機，你可以在Windows機器上分享它，然後讓其它系統來使用它來打印。</p><p>在幾年之前，我遇到了這個問題，那時大多數打印機生產商不支持Linux系統。我有一台老式的只支持Windows和Mac OS X但卻不支持Linux的打印機。（譯註：除非是特別冷門的打印機，現在一般都可以在Linux進行打印操作了。在譯者看來，本文的理由不成立，不過做法成立。）</p><p>我在我的Windows機器上安裝了打印機驅動，然後它就可以很好的工作咯。我的Windows機器使用它來打印非常好，但是我的Ubuntu卻無法使用它來打印，因為打印機並不支持LAN接口。</p><p>所以，我在Windows上共享該打印機，然後我的Ubuntu機器就可以使用合適的字體和風格進行打印咯。假如你也遇到類似的情景，你可以按照下面的指導來操作。</p><p>首先，登入Windows，右擊你要共享的打印機，然後點擊‘<strong>Printer properties（打印機屬性）</strong>’</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu.png" alt=""></p><p>接着，選擇“<strong>Sharing（共享）</strong>”標籤頁，勾選‘<strong>Share this printer（共享這台打印機）</strong>’複選框來共享。記住共享打印機的名字，因為你要使用這個共享名來連接這台打印機。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu1.png" alt=""></p><p>最後，以管理員權限運行命令列終端，運行以下命令以便於文件和打印機可以通過防火牆實現共享。</p><pre><code>netsh advfirewall firewall set rule group=&quot;File and Printer Sharing&quot; new enable=Yes
</code></pre><p>接着，登入Ubuntu中，選擇頂部面板右邊的<strong>齒輪</strong>，然後選擇<strong>系統設置...</strong></p><p>系統設置打開後，選擇打印機，然後點擊<strong>添加</strong>。當跳出來一個窗口讓你選擇設備時，選擇‘<strong>Windows Printer via SAMBA（使用SAMBA的Windows打印機）</strong>’。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu2.png" alt=""></p><p>鍵入Windows電腦的IP地址或者主機名，後面接着鍵入共享的打印機名。你可能需要鍵入你的windows驗證信息（用户名和密碼）。點擊瀏覽來驗證你是否可以看到打印機，當你完成這些後，就可以點擊下一步繼續。</p><p>接着，選擇打印機品牌和型號。假如你在列表中看不到特定的型號，選擇一個最接近它的然後繼續。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu3.png" alt=""></p><p>以上這些都搞定了之後，你的打印機就已安裝好，可以使用嘍。</p><p><img src="http://www.liberiangeek.net/wp-content/uploads/2013/11/printersharingubuntu4.png" alt=""></p><p>好好享受吧！</p><hr>`,22)),s("p",null,[t[1]||(t[1]=n("via: ",-1)),r(i,{href:"http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-print-from-shared-windows-printers/"},{default:e(()=>[...t[0]||(t[0]=[n("http://www.liberiangeek.net/2013/11/daily-ubuntu-tips-print-from-shared-windows-printers/",-1)])]),_:1})]),s("p",null,[t[4]||(t[4]=n("譯者：",-1)),r(i,{href:"https://github.com/Linux-pdz"},{default:e(()=>[...t[2]||(t[2]=[n("Linux-pdz",-1)])]),_:1}),t[5]||(t[5]=n(" 校對：",-1)),r(i,{href:"https://github.com/carolinewuyan"},{default:e(()=>[...t[3]||(t[3]=[n("Caroline",-1)])]),_:1})]),s("p",null,[t[8]||(t[8]=n("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:e(()=>[...t[6]||(t[6]=[n("LCTT",-1)])]),_:1}),t[9]||(t[9]=n(" 原創翻譯，",-1)),r(i,{href:"http://linux.cn/"},{default:e(()=>[...t[7]||(t[7]=[n("Linux中國",-1)])]),_:1}),t[10]||(t[10]=n(" 榮譽推出",-1))])])}const P=p(w,[["render",l]]);export{x as __pageData,P as default};
